package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.calendar.*;import com.rpb.reservation.workforce.calendar.annual.*;import static com.rpb.reservation.workforce.calendar.annual.HolidayDtos.*;
import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.attendance.AttendanceAccess;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceHolidayYearPostgresTest extends WorkforcePostgresTest {
 PublicHolidayService years;StoreRestMonthService months;CalendarRepository calendar;CalendarService calendarService;WorkforceJson json;
 @BeforeEach void holidays(TestInfo info){if(info.getTestMethod().orElseThrow().getDeclaringClass()!=WorkforceHolidayYearPostgresTest.class)return;var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();json=new WorkforceJson(mapper);var audit=new WorkforceAudit(logs,mapper);var schedules=new SchedulingRepository(jdbc,json);calendar=new CalendarRepository(jdbc);calendarService=proxy(new CalendarService(access,new AttendanceAccess(access,repository,schedules),schedules,calendar,audit));years=proxy(new PublicHolidayService(access,new HolidayYearRepository(jdbc),audit));months=proxy(new StoreRestMonthService(access,calendar,calendarService,schedules,json));}
 @Test void observedHolidayWithoutEnglishNameKeepsNameFallback(){var date=LocalDate.of(2026,8,9);years.save(admin,store,2026,new Write(0L,List.of(new Holiday(UUID.randomUUID(),date,"自定义节日","",date.plusDays(1),"agreed",true,false))));var projected=calendar.list(tenant,store,date.plusDays(1),date.plusDays(1)).getFirst();assertThat(projected.englishName()).isEmpty();assertThat(projected.name()).isEqualTo("自定义节日（约定补休）");}
 @Test void templatesAreTenantScopedAndProjectElevenHolidaysAndCorrectSundayDates(){var t=years.template(admin,store,2026);assertThat(t.items()).hasSize(11);assertThat(t.items()).filteredOn(h->h.observedOn()!=null).hasSize(3);var saved=years.save(admin,store,2026,new Write(0L,t.items()));assertThat(saved.version()).isEqualTo(1);assertThat(years.save(admin,store,2026,new Write(0L,t.items()))).isEqualTo(saved);assertThat(calendar.list(tenant,store,LocalDate.of(2026,1,1),LocalDate.of(2026,12,31))).hasSize(14);assertThat(calendar.list(tenant,sibling,LocalDate.of(2026,11,8),LocalDate.of(2026,11,9))).hasSize(2);assertThat(t.items().stream().filter(h->h.date().equals(LocalDate.of(2026,3,21))).findFirst().orElseThrow().observedOn()).isNull();var next=years.template(admin,store,2027);assertThat(next.items()).hasSize(11);assertThat(next.items()).filteredOn(h->h.observedOn()!=null).singleElement().extracting(Holiday::observedOn).isEqualTo(LocalDate.of(2027,2,8));}
 @Test void unchangedHolidayRowsAndLegacyJsonKeepStableSourceEvidence(){var id=UUID.randomUUID();var legacy=calendarService.save(admin,store,id,new CalendarDtos.CalendarWrite(0L,LocalDate.of(2026,10,29),"store_rest","Original",true));var tree=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().valueToTree(legacy);assertThat(tree.size()).isEqualTo(6);var before=json.write(calendar.list(tenant,store,legacy.date(),legacy.date()));var rows=years.template(admin,store,2026).items();years.save(admin,store,2026,new Write(0L,rows));assertThat(json.write(calendar.list(tenant,store,legacy.date(),legacy.date()))).isEqualTo(before);var january=calendar.list(tenant,store,LocalDate.of(2026,1,1),LocalDate.of(2026,1,1));var changed=new ArrayList<>(rows);var row=changed.get(1);changed.set(1,new Holiday(row.id(),row.date(),row.name()+" adjusted",row.englishName(),row.observedOn(),row.observedKind(),row.enabled(),row.tentative()));years.save(admin,store,2026,new Write(1L,changed));assertThat(calendar.list(tenant,store,LocalDate.of(2026,1,1),LocalDate.of(2026,1,1))).isEqualTo(january);assertThatThrownBy(()->years.save(admin,store,2026,new Write(0L,rows))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);}
 @Test void monthlyMultiSelectPreservesPublicEventsOtherStoresAndOriginalNames(){var first=LocalDate.of(2027,1,4);calendarService.save(admin,store,UUID.randomUUID(),new CalendarDtos.CalendarWrite(0L,first,"public_holiday","Custom holiday",true));calendarService.save(admin,sibling,UUID.randomUUID(),new CalendarDtos.CalendarWrite(0L,first,"store_rest","Other store",true));var old=months.get(admin,store,"2027-01");var write=new MonthWrite(old.fingerprint(),List.of(first,first.plusDays(2)));var saved=months.save(admin,store,"2027-01",write);assertThat(saved.dates()).containsExactly(first,first.plusDays(2));assertThat(months.save(admin,store,"2027-01",write)).isEqualTo(saved);assertThat(months.get(admin,sibling,"2027-01").dates()).containsExactly(first);assertThat(calendar.list(tenant,store,first,first).stream().anyMatch(e->e.name().equals("Custom holiday")&&e.enabled())).isTrue();assertThatThrownBy(()->months.save(admin,store,"2027-01",new MonthWrite(old.fingerprint(),List.of(first)))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);months.save(admin,store,"2027-01",new MonthWrite(saved.fingerprint(),List.of()));assertThat(calendar.list(tenant,store,first,first)).anyMatch(e->e.kind().equals("store_rest")&&!e.enabled());}
 @Test void managerCannotWriteSharedYearsButCanMaintainOnlyAuthorizedStore(){var id=account("store_manager",Set.of(store),Set.of("workforce.view"));jdbc.update("insert into workforce_administrators(tenant_id,store_id,account_id,employee_manage,version) values(?,?,?,true,1)",tenant,store,id);var manager=new CurrentActor(tenant,id,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));assertThat(years.get(manager,store,2026).items()).isEmpty();assertThatThrownBy(()->years.save(manager,store,2026,new Write(0L,years.template(manager,store,2026).items()))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);assertThat(months.get(manager,store,"2026-11").dates()).isEmpty();assertThatThrownBy(()->months.get(manager,sibling,"2026-11")).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}
 @Test void failedAnnualAuditRollsBackAndInvalidDatesAreRejected(){doThrow(new IllegalStateException("audit failed")).when(logs).append(any(com.rpb.reservation.common.scope.StoreScope.class),any());assertThatThrownBy(()->years.save(admin,store,2026,new Write(0L,years.template(admin,store,2026).items()))).isInstanceOf(IllegalStateException.class);assertThat(years.get(admin,store,2026).version()).isZero();var h=years.template(admin,store,2027).items().getFirst();assertThatThrownBy(()->years.save(admin,store,2026,new Write(0L,List.of(h)))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);assertThatThrownBy(()->months.save(admin,store,"2027-01",new MonthWrite("a".repeat(64),List.of(LocalDate.of(2027,2,1))))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);}
 @Test void templatesDoNotCollideAcrossTenantsAndCrossYearCompensationIsVisible(){var foreign=new CurrentActor(UUID.randomUUID(),adminId,"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThat(years.template(admin,store,2026).items()).extracting(Holiday::id).doesNotContainAnyElementsOf(years.template(foreign,store,2026).items().stream().map(Holiday::id).toList());var h=new Holiday(UUID.randomUUID(),LocalDate.of(2027,12,31),"跨年补休测试","Year-end example",LocalDate.of(2028,1,3),"agreed",true,false);years.save(admin,store,2027,new Write(0L,List.of(h)));var events=calendar.list(tenant,sibling,LocalDate.of(2028,1,3),LocalDate.of(2028,1,3));assertThat(events).singleElement().satisfies(e->{assertThat(e.originDate()).isEqualTo(h.date());assertThat(e.observed()).isTrue();});assertThatThrownBy(()->years.save(admin,store,2028,new Write(0L,List.of(new Holiday(h.id(),LocalDate.of(2028,12,31),h.name(),h.englishName(),null,"none",true,false))))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);assertThat(years.get(admin,store,2028).version()).isZero();}
 @Test void sharedYearConcurrentChangesCannotOverwriteEachOther()throws Exception{var rows=years.template(admin,store,2026).items();var changed=new ArrayList<>(rows);var h=changed.getFirst();changed.set(0,new Holiday(h.id(),h.date(),h.name()+" other",h.englishName(),h.observedOn(),h.observedKind(),h.enabled(),h.tentative()));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(()->attempt(store,rows));var two=pool.submit(()->attempt(sibling,changed));assertThat(List.of(one.get(20,java.util.concurrent.TimeUnit.SECONDS),two.get(20,java.util.concurrent.TimeUnit.SECONDS))).containsExactlyInAnyOrder("ok","conflict");}assertThat(years.get(admin,store,2026).version()).isEqualTo(1);}
 private String attempt(UUID shop,List<Holiday> rows){try{years.save(admin,shop,2026,new Write(0L,rows));return "ok";}catch(WorkforceException e){if(e.status()!=409)throw e;return "conflict";}}
 @Test void gateDenialsProtectBothAnnualAndStoreSettings(){for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(any());assertThatThrownBy(()->years.get(admin,store,2026)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);assertThatThrownBy(()->months.get(admin,store,"2026-11")).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}}
}
